cssCode:
.scan-container {
  width: 150px; height: 150px; position: relative;
  display: flex; align-items: center; justify-content: center;
}
.face-icon {
  width: 100px; height: 100px;
  border: 3px dashed rgba(0, 255, 204, 0.4); border-radius: 20px;
  position: relative; overflow: hidden;
}
.laser-bar {
  position: absolute; top: 0; left: 0; width: 100%; height: 4px;
  background: #00ffcc; box-shadow: 0 0 15px 5px rgba(0, 255, 204, 0.6);
  animation: scanFace 2s infinite alternate ease-in-out;
}
.scan-brackets {
  position: absolute; width: 100%; height: 100%;
  border: 4px solid transparent; border-top-color: #ff007f; border-bottom-color: #ff007f;
  border-radius: 30px; animation: pulseBracket 1.5s infinite alternate;
}
@keyframes scanFace { 0% { top: 0; } 100% { top: 96px; } }
@keyframes pulseBracket { 0% { transform: scale(1); opacity: 0.5; } 100% { transform: scale(1.1); opacity: 1; } }

