const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const container = document.createElement('div');
container.className = 'scan-container';

const brackets = document.createElement('div');
brackets.className = 'scan-brackets';

const icon = document.createElement('div');
icon.className = 'face-icon';
icon.innerHTML = '<div style="font-size: 60px; text-align: center; line-height: 100px; opacity: 0.7;">👤</div>';

const laser = document.createElement('div');
laser.className = 'laser-bar';

icon.appendChild(laser);
container.appendChild(brackets);
container.appendChild(icon);
c.appendChild(container);
